var r=`1117-cheeseburger`;var t=`world-1117`;var n=`US`;var s=`northern-america`;var a=4;var o=35;var l={en:`Cheeseburger`,ua:`Чизбургер`};var d={en:`Cheeseburger is a dish from United States prepared with ground beef, burger bun, cheddar cheese, lettuce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Чизбургер, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: яловичий фарш, булочка для бургера, сир чедер, салат латук. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`ground-beef`,680,`g`],[`table-salt`,8,`g`],[`ground-black-pepper`,5,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Grill over medium-high heat for about 12 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 12 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:12,i:[[`canola-oil`,20,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`burger-bun`,4,`pcs`],[`cheddar-cheese`,140,`g`],[`lettuce`,120,`g`],[`tomato`,170,`g`],[`pickled-cucumber`,130,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ketchup`,90,`g`],[`yellow-mustard`,55,`g`]]}];var u={slug:r,id:t,country:`US`,region:s,servings:4,minutes:35,title:l,text:d,steps:g};export{n as country,u as default,t as id,o as minutes,s as region,a as servings,r as slug,g as steps,d as text,l as title};